create policy authenticated_private_broadcast_read on realtime.messages for select to authenticated using (realtime.topic() like 'club:%' and private.has_club_role(split_part(realtime.topic(),':',2)::uuid,array['owner','organizer','score_official','staff','member']::public.club_role[]));
create or replace function private.broadcast_invalidation() returns trigger language plpgsql security definer set search_path=pg_catalog,public,private,realtime as $$ begin perform realtime.broadcast_changes(tg_table_name||':'||coalesce(new.id,old.id)::text,tg_op,tg_op,tg_table_name,tg_table_schema,new,old); return coalesce(new,old); end $$;
